import sys
from collections import defaultdict

MOD = 10**9 + 7

def dfs(u, p, xor_path):
    global edges, graph, n, result
    if u != p:
        xor_path ^= edges[(u, p)]
    if xor_path in paths[u]:
        paths[u][xor_path] += 1
    else:
        paths[u][xor_path] = 1
    for v in graph[u]:
        if v != p:
            dfs(v, u, xor_path)

def main():
    global edges, graph, n, result, paths
    n, m = map(int, sys.stdin.readline().split())
    graph = defaultdict(list)
    edges = {}
    for _ in range(m):
        u, v, t = map(int, sys.stdin.readline().split())
        graph[u].append(v)
        graph[v].append(u)
        edges[(u, v)] = t
        edges[(v, u)] = t

    result = 0
    paths = [defaultdict(int) for _ in range(n+1)]

    for i in range(1, n+1):
        dfs(i, i, 0)

    for u in range(1, n+1):
        for xor_val, count in paths[u].items():
            result += xor_val * count * (count - 1) // 2
            result %= MOD

    print(result)

if __name__ == "__main__":
    main()
